// A Bot key or the sign-in secret. The owner of this process may read it.
// Nobody else on the machine may.
export function lockPrivateFile(file) {
  try {
    chmodSync(file, 0o600);
  } catch {
    // Windows ignores the mode. The ACL below is what actually restricts it.
  }
  if (process.platform !== 'win32') return;
  try {
    const who = execFileSync('whoami', { encoding: 'utf8' }).trim();
    execFileSync('icacls', [file, '/inheritance:r', '/grant:r', `${who}:(R,W)`], { stdio: 'ignore' });
  } catch {
    // Still written. The file is gitignored either way.
  }
}

