async function toolText(key, name, args = {}) {
  const res = await fetch(`${base}/mcp`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args } }),
  });
  const body = await res.json();
  return { status: res.status, error: body.result?.isError === true, text: body.result?.content?.[0]?.text || '' };
}

test('new tools stay inside the account, and answers do not carry keys', async () => {
  const a = await newAccount('toolA');
  const b = await newAccount('toolB');
  const schools = [{ name: 'Stanford University', status: 'target', state: 'CA', notes: a.key }];
  assert.equal((await call('POST', '/api/profile', { name: 'T toolA', visa_type: 'f1_opt', schools }, { cookie: a.cookie })).status, 200);
  assert.equal((await call('POST', '/api/profile', { name: 'T toolB', visa_type: 'f1_opt', schools: [{ name: 'Stanford University', status: 'target', state: 'CA' }] }, { cookie: b.cookie })).status, 200);
  const aId = (await call('GET', '/api/store', undefined, { cookie: a.cookie })).json.profiles[0].id;
  const bId = (await call('GET', '/api/store', undefined, { cookie: b.cookie })).json.profiles[0].id;

  const listed = await toolText(a.key, 'list_people');
  assert.equal(listed.error, false);
  assert.ok(!listed.text.includes(bId));
  assert.ok(!listed.text.includes(a.key), 'list_people returned the Bot key');
  assert.match(listed.text, /ending \d{2}/);
  assert.equal((await toolText(a.key, 'get_brief', { person: bId })).error, true);
  assert.equal((await toolText(a.key, 'list_applications', { person: bId })).error, true);
  assert.equal((await toolText(a.key, 'get_application_bank', { person: bId })).error, true);
  assert.equal((await toolText(a.key, 'save_bank_fact', { person: bId, field: 'name', value: 'Stolen Name', source: 'document' })).error, true);
  assert.equal((await toolText(a.key, 'save_school_signal', { person: bId, school_name: 'Stanford University', signal: 'isss_office', value: true, source_url: 'https://bechtel.stanford.edu/' })).error, true);

  const mine = await toolText(a.key, 'save_school_signal', { school_name: 'Stanford University', signal: 'isss_office', value: true, source_url: 'https://bechtel.stanford.edu/' });
  assert.equal(mine.error, false);
  const theirs = await call('GET', '/api/store', undefined, { cookie: b.cookie });
  assert.equal(theirs.json.school_signals.length, 0);
  const bank = await toolText(a.key, 'get_application_bank', { person: aId });
  assert.equal(bank.error, false);
  assert.ok(!bank.text.includes(a.key));

  await call('POST', '/api/connect/webhook', { url: 'https://example.com/hook', key: 'webhook-secret-value' }, { cookie: a.cookie });
  const again = await toolText(a.key, 'list_schools', { person: aId });
  assert.ok(!again.text.includes('webhook-secret-value'));
  assert.ok(!again.text.includes(a.key), 'a school note echoed the Bot key');

  const sample = await call('GET', '/api/store', undefined, { cookie: a.cookie });
  assert.equal(sample.json.alerts.some((row) => !row.person), false);
});

test('private key files are readable only by this user', async () => {
  const keyFile = path.join(dataDir, 'bot-key.txt');
  const accountsFile = path.join(dataDir, 'accounts.json');
  if (process.platform === 'win32') {
    for (const file of [keyFile, accountsFile]) {
      const acl = execFileSync('icacls', [file], { encoding: 'utf8' });
      assert.equal(/Everyone|BUILTIN\\Users|Authenticated Users|NT AUTHORITY\\Authenticated Users/i.test(acl), false, file);
    }
  } else {
    const { stat } = await import('node:fs/promises');
    for (const file of [keyFile, accountsFile]) assert.equal((await stat(file)).mode & 0o777, 0o600);
  }
});

