import { randomBytes } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';

const accountsPath = 'C:/Users/abhim/Desktop/waypoint/data/accounts.json';
const keyPath = 'C:/Users/abhim/Desktop/waypoint/data/bot-key.txt';
const accounts = JSON.parse(readFileSync(accountsPath, 'utf8'));
accounts.secret = randomBytes(32).toString('hex');
accounts.bot_key = `wpb_${randomBytes(24).toString('hex')}`;
writeFileSync(accountsPath, `${JSON.stringify(accounts, null, 2)}\n`);
writeFileSync(keyPath, `${accounts.bot_key}\n`);

const who = execFileSync('whoami', { encoding: 'utf8' }).trim();
for (const file of [accountsPath, keyPath]) {
  execFileSync('icacls', [file, '/inheritance:r', '/grant:r', `${who}:(R,W)`], { stdio: 'ignore' });
}

const repo = 'vihaanbussa/waypoint-hackathon';
let failed = false;
for (const [name, value] of [
  ['WAYPOINT_SECRET', accounts.secret],
  ['WAYPOINT_BOT_KEY', accounts.bot_key],
]) {
  const result = spawnSync('gh', ['secret', 'set', name, '--repo', repo], { input: value, encoding: 'utf8' });
  if (result.status !== 0) {
    failed = true;
    const err = `${result.stderr || ''}${result.stdout || ''}`.replace(/wpb_[0-9a-f]+/gi, '[redacted]').replace(/[0-9a-f]{32,}/gi, '[redacted]');
    console.error(`${name} not linked: ${err.slice(0, 400) || 'gh failed'}`);
  } else {
    console.log(`${name} linked to GitHub`);
  }
}
if (failed) process.exit(1);
